<script setup lang="ts">
import {ref,watch} from 'vue';import {http} from '../../api/http';import {allOptions} from '../../api/options';import type {Row} from '../../shared/records'
const props=defineProps<{site?:number;menuId?:number;date:string;meal:string}>(),emit=defineEmits<{applied:[date:string,meal:string]}>(),dialog=ref(''),targetDate=ref(''),targetMeal=ref('LUNCH'),weekStart=ref(''),name=ref(''),templates=ref<Row[]>([]),templateId=ref<number>(),error=ref(''),pending=ref(false),message=ref('')
function monday(date:string){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
async function open(mode:string){dialog.value=mode;error.value='';message.value='';targetDate.value=props.date;targetMeal.value=props.meal;weekStart.value=monday(props.date);name.value='';if(mode==='apply')try{templates.value=await allOptions(`/sites/${props.site}/menu-templates`)}catch(e){error.value=(e as Error).message}}
async function submit(){if(!props.site||pending.value)return;pending.value=true;error.value='';try{let first:Row|undefined;
 if(dialog.value==='copy')first=await http.post(`/sites/${props.site}/menus/${props.menuId}/copy`,{serviceDate:targetDate.value,mealType:targetMeal.value});
 else if(dialog.value==='save')await http.post(`/sites/${props.site}/menu-templates`,{name:name.value,weekStart:weekStart.value});
 else {if(!templateId.value)throw new Error('请选择周模板');const data=await http.post<never,Row>(`/sites/${props.site}/menu-templates/${templateId.value}/apply`,{weekStart:weekStart.value});first=data.menus[0]}
 message.value=dialog.value==='save'?'周模板已保存':'已生成草稿，请重新核对食材、过敏原、价格和份数后上报';dialog.value='';if(first)emit('applied',first.serviceDate,first.mealType)
 }catch(e){error.value=(e as Error).message}finally{pending.value=false}}
async function remove(){if(!templateId.value)return;pending.value=true;try{await http.delete(`/sites/${props.site}/menu-templates/${templateId.value}`);templateId.value=undefined;templates.value=await allOptions(`/sites/${props.site}/menu-templates`)}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
watch(()=>props.site,()=>{dialog.value='';templateId.value=undefined})
</script><template><div class="toolbar"><el-button :disabled="!menuId" @click="open('copy')">复制当前菜谱</el-button><el-button @click="open('save')">保存整周模板</el-button><el-button @click="open('apply')">应用周模板</el-button></div><el-alert v-if="message" :title="message" type="success" :closable="false"/><el-dialog :model-value="!!dialog" :title="dialog==='copy'?'复制菜谱为草稿':dialog==='save'?'保存整周模板':'应用周模板为草稿'" width="min(660px,94vw)" @close="dialog=''"><p>只生成草稿，目标日期餐次存在菜谱时整次操作取消。周模板保存周一至周日已有菜谱，不补造缺失餐次。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="form-stack" @submit.prevent="submit"><template v-if="dialog==='copy'"><label for="copy-date">目标供餐日期</label><el-input id="copy-date" v-model="targetDate" type="date"/><el-select v-model="targetMeal" aria-label="目标餐次"><el-option label="午餐" value="LUNCH"/><el-option label="晚餐" value="DINNER"/></el-select></template><template v-else><label for="template-week">{{dialog==='save'?'来源周的周一':'目标周的周一'}}</label><el-input id="template-week" v-model="weekStart" type="date"/><template v-if="dialog==='save'"><label for="template-name">模板名称</label><el-input id="template-name" v-model="name"/></template><el-select v-else v-model="templateId" aria-label="选择周模板" filterable><el-option v-for="t in templates" :key="t.id" :value="t.id" :label="t.name"/></el-select></template><el-button native-type="submit" type="primary" :loading="pending">{{dialog==='save'?'保存周模板':'确认生成草稿'}}</el-button><el-button v-if="dialog==='apply'&&templateId" :loading="pending" @click="remove">删除选中模板</el-button></form></el-dialog></template>
